WITH with_windows AS (SELECT *, LAG(quantity, 1) OVER (PARTITION BY product_id ORDER BY quantity, id) AS prev_quantity, COUNT(quantity) OVER (PARTITION BY store_id) AS store_id_count_quantity, NTILE(10) OVER (PARTITION BY product_id ORDER BY quantity DESC, id) AS quantity_bucket FROM inventory WHERE store_id = 5) SELECT DATE_TRUNC('QUARTER', last_restock) AS quarter_start, store_id, BIT_OR(quantity) AS quantity_bit_or, ROUND(AVG(quantity_bucket), 2) AS avg_quantity_bucket, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, BIT_OR(quantity) AS quantity_bit_or_2 FROM with_windows GROUP BY DATE_TRUNC('QUARTER', last_restock), store_id;
